import enum
import uuid
from datetime import date

from sqlalchemy import Boolean, Date, Enum, ForeignKey, Index, String, Uuid, text
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.db.base import Base
from app.db.mixins import TimestampMixin, UUIDPrimaryKeyMixin
from app.models.stored_file import StoredFile


class SexAtBirth(enum.StrEnum):
    female = "female"
    male = "male"
    intersex = "intersex"
    unknown = "unknown"


# Generated by the database from a sequence, so two concurrent registrations
# can never receive the same number. The sequence is created by the migration.
MRN_DEFAULT = text("('MRN' || lpad(nextval('patient_mrn_seq')::text, 8, '0'))")


class Patient(UUIDPrimaryKeyMixin, TimestampMixin, Base):
    """The patient's legal/administrative identity — not their medical history
    (clinical data lives in its own tables, architecture §10).

    ``user_id`` is nullable: reception registers walk-in patients who may never
    have a login; an account can be linked later.
    """

    __tablename__ = "patients"
    __table_args__ = (Index("ix_patients_last_name_first_name", "last_name", "first_name"),)
    # Fetch the server-generated MRN (and other defaults) with RETURNING on insert.
    __mapper_args__ = {"eager_defaults": True}

    user_id: Mapped[uuid.UUID | None] = mapped_column(
        Uuid, ForeignKey("users.id", ondelete="RESTRICT"), unique=True
    )
    mrn: Mapped[str] = mapped_column(String(20), unique=True, server_default=MRN_DEFAULT)

    first_name: Mapped[str] = mapped_column(String(100))
    last_name: Mapped[str] = mapped_column(String(100))
    date_of_birth: Mapped[date] = mapped_column(Date, index=True)
    sex_at_birth: Mapped[SexAtBirth] = mapped_column(
        Enum(SexAtBirth, name="sex_at_birth", values_callable=lambda e: [m.value for m in e]),
        default=SexAtBirth.unknown,
    )

    # Contact details: may differ from the login email on User.
    phone: Mapped[str | None] = mapped_column(String(30), index=True)
    email: Mapped[str | None] = mapped_column(String(255))
    address: Mapped[str | None] = mapped_column(String(500))
    preferred_language: Mapped[str | None] = mapped_column(String(35))

    registered_by_user_id: Mapped[uuid.UUID | None] = mapped_column(
        Uuid, ForeignKey("users.id", ondelete="SET NULL")
    )
    # Deactivated, never deleted (architecture §20).
    is_active: Mapped[bool] = mapped_column(Boolean, default=True)
    # Profile photo in R2; NULL shows the initials/illustration avatar.
    photo_file_id: Mapped[uuid.UUID | None] = mapped_column(
        Uuid, ForeignKey("stored_files.id", ondelete="RESTRICT"), unique=True
    )
    # Joined into every load of the profile, so responses can sign the photo
    # URL without another query. (A future SELECT ... FOR UPDATE on this
    # table must use with_for_update(of=<Model>): PostgreSQL refuses to lock
    # the nullable side of an outer join.)
    photo: Mapped[StoredFile | None] = relationship(lazy="joined")

    @property
    def full_name(self) -> str:
        return f"{self.first_name} {self.last_name}"
